class ProductModel {
  final String id;
  final String name;
  final String description;
  final String aboutDish;
  final List<String> labels;
  final double discountPercent;
  final double price;
  /// Generated by PostgreSQL from price and discount_percent; never write this field directly.
  final double? discountedPrice;
  final String? categoryId;
  final String? categoryName;
  /// Inventory is not tracked in public.products currently; do not treat as authoritative.
  final int? stock;
  final String imageUrl;
  final String status; // Derived from is_active.
  final bool isPopular;
  final double? rating;
  final int? reviewCount;
  final DateTime createdAt;

  const ProductModel({
    required this.id,
    required this.name,
    required this.description,
    this.aboutDish = '',
    this.labels = const [],
    this.discountPercent = 0,
    required this.price,
    this.discountedPrice,
    this.categoryId,
    this.categoryName,
    this.stock,
    required this.imageUrl,
    required this.status,
    this.isPopular = false,
    this.rating,
    this.reviewCount,
    required this.createdAt,
  });

  factory ProductModel.fromJson(Map<String, dynamic> json) {
    final category = json['categories'];
    final bool active = json['is_active'] as bool? ?? ((json['status'] ?? 'active') == 'active');
    return ProductModel(
      id: json['id'].toString(),
      name: (json['name'] ?? '').toString(),
      description: (json['description'] ?? '').toString(),
      aboutDish: (json['about_dish'] ?? '').toString(),
      labels: json['labels'] is List ? (json['labels'] as List).map((v) => v.toString()).where((v) => v.trim().isNotEmpty).toList(growable: false) : const <String>[],
      discountPercent: (json['discount_percent'] as num? ?? 0).toDouble(),
      price: (json['price'] as num? ?? 0).toDouble(),
      discountedPrice: json['discounted_price'] is num ? (json['discounted_price'] as num).toDouble() : null,
      categoryId: json['category_id']?.toString(),
      categoryName: category is Map ? category['name']?.toString() : json['category_name']?.toString(),
      stock: json['stock'] is num ? (json['stock'] as num).toInt() : null,
      imageUrl: (json['image_url'] ?? '').toString(),
      status: active ? 'active' : 'inactive',
      isPopular: json['is_popular'] as bool? ?? false,
      rating: json['rating'] is num ? (json['rating'] as num).toDouble() : null,
      reviewCount: json['review_count'] is num ? (json['review_count'] as num).toInt() : null,
      createdAt: DateTime.tryParse((json['created_at'] ?? '').toString()) ?? DateTime.fromMillisecondsSinceEpoch(0, isUtc: true),
    );
  }

  /// Only database-backed product fields are emitted.
  Map<String, dynamic> toJson() => {
        'id': id,
        'name': name,
        'description': description,
        'about_dish': aboutDish,
        'labels': labels,
        'discount_percent': discountPercent,
        'price': price.round(),
        'image_url': imageUrl,
        'is_active': status == 'active',
        'is_popular': isPopular,
        'rating': rating,
        'review_count': reviewCount,
        'category_id': categoryId,
        'created_at': createdAt.toIso8601String(),
      };

  ProductModel copyWith({
    String? id,
    String? name,
    String? description,
    String? aboutDish,
    List<String>? labels,
    double? discountPercent,
    double? price,
    double? discountedPrice,
    String? categoryId,
    String? categoryName,
    int? stock,
    String? imageUrl,
    String? status,
    bool? isPopular,
    double? rating,
    int? reviewCount,
    DateTime? createdAt,
  }) => ProductModel(
        id: id ?? this.id,
        name: name ?? this.name,
        description: description ?? this.description,
        aboutDish: aboutDish ?? this.aboutDish,
        labels: labels ?? this.labels,
        discountPercent: discountPercent ?? this.discountPercent,
        price: price ?? this.price,
        discountedPrice: discountedPrice ?? this.discountedPrice,
        categoryId: categoryId ?? this.categoryId,
        categoryName: categoryName ?? this.categoryName,
        stock: stock ?? this.stock,
        imageUrl: imageUrl ?? this.imageUrl,
        status: status ?? this.status,
        isPopular: isPopular ?? this.isPopular,
        rating: rating ?? this.rating,
        reviewCount: reviewCount ?? this.reviewCount,
        createdAt: createdAt ?? this.createdAt,
      );
}
